#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    while (cin >> n) {
        vector<long long> roots(n);
        for (auto &r : roots) cin >> r;
        vector<long long> poly = {1};
        for (long long r : roots) {
            vector<long long> np(poly.size()+1, 0);
            for (size_t i=0;i<poly.size();i++){
                np[i] += -r*poly[i];
                np[i+1] += poly[i];
            }
            poly = np;
        }
        ostringstream oss;
        if (n==1) oss << "x"; else oss << "x^" << n;
        for (int i=n-1;i>=1;i--){
            long long c = poly[i];
            if (c==0) continue;
            oss << (c<0 ? " - " : " + ");
            long long ac = llabs(c);
            if (ac!=1) oss << ac;
            if (i==1) oss << "x"; else oss << "x^" << i;
        }
        long long c0 = poly[0];
        oss << (c0<0 ? " - " : " + ") << llabs(c0);
        oss << " = 0";
        cout << oss.str() << "\n";
    }
}

